function t(lang: Lang, key: keyof typeof copy.en) { return copy[lang][key]; }
function money(value: number | undefined, currency: string) { return `${currency === 'USD' ? '$' : 'G'}${(value || 0).toLocaleString('en-US', { minimumFractionDigits: currency === 'USD' ? 2 : 0 })}`; }
function date(value?: string | null) { return value ? new Date(value).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : '—'; }
function initials(first?: string, last?: string) { return `${first?.[0] || 'D'}${last?.[0] || 'J'}`.toUpperCase(); }

function Logo({ small = false }: { small?: boolean }) {
  return <Link href="/" className={`flex items-center gap-3 ${small ? 'justify-center' : ''}`} data-testid="link-home">
    <span className="grid size-10 shrink-0 place-items-center rounded-xl bg-[hsl(var(--sidebar-primary))] text-[hsl(var(--sidebar-primary-foreground))] shadow-sm">
      <span className="text-xl font-bold">+</span>
    </span>
    {!small && <span><span className="block text-[15px] font-bold tracking-tight">Sourire Clair</span><span className="eyebrow text-[hsl(var(--sidebar-foreground)/.55)]">Haiti · clinic workspace</span></span>}
  </Link>;
}

function Modal({ title, children, onClose, wide = false }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  return <div className="fixed inset-0 z-50 grid place-items-center bg-[hsl(var(--foreground)/.38)] p-4 backdrop-blur-sm" role="dialog" aria-modal="true">
    <div className={`max-h-[92dvh] w-full overflow-auto rounded-2xl border border-border bg-card p-6 shadow-2xl ${wide ? 'max-w-3xl' : 'max-w-xl'} fade-in`}>
      <div className="mb-5 flex items-start justify-between gap-4"><div><p className="eyebrow text-primary">Sourire Clair</p><h2 className="mt-1 text-xl font-bold">{title}</h2></div><button type="button" onClick={onClose} className="rounded-lg p-2 text-muted-foreground hover:bg-muted" data-testid="button-close-modal"><X size={18} /></button></div>
      {children}
    </div>
  </div>;
}

function Field({ label, name, value, onChange, type = 'text', placeholder, required = false }: { label: string; name: string; value?: string | number | null; onChange?: (value: string) => void; type?: string; placeholder?: string; required?: boolean }) {
  return <label className="block space-y-1.5"><span className="text-xs font-semibold text-muted-foreground">{label}{required && <span className="text-destructive"> *</span>}</span><input name={name} required={required} type={type} value={value ?? ''} placeholder={placeholder} onChange={e => onChange?.(e.target.value)} className="h-10 w-full rounded-lg border border-input bg-background px-3 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15" data-testid={`input-${name}`} /></label>;
}
function TextField({ label, name, value, onChange, placeholder }: { label: string; name: string; value?: string | null; onChange?: (value: string) => void; placeholder?: string }) {
  return <label className="block space-y-1.5"><span className="text-xs font-semibold text-muted-foreground">{label}</span><textarea name={name} rows={3} value={value ?? ''} placeholder={placeholder} onChange={e => onChange?.(e.target.value)} className="w-full resize-none rounded-lg border border-input bg-background px-3 py-2 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/15" data-testid={`textarea-${name}`} /></label>;
}
function Button({ children, onClick, variant = 'primary', type = 'button', disabled = false, testId }: { children: ReactNode; onClick?: () => void; variant?: 'primary' | 'outline' | 'quiet' | 'coral' | 'danger'; type?: 'button' | 'submit'; disabled?: boolean; testId?: string }) {
  return <button type={type} onClick={onClick} disabled={disabled} className={`inline-flex h-10 items-center justify-center gap-2 rounded-lg px-3.5 text-sm font-semibold transition active:scale-[.98] disabled:cursor-not-allowed disabled:opacity-50 ${variant === 'primary' ? 'bg-primary text-primary-foreground shadow-sm hover:brightness-95' : variant === 'coral' ? 'bg-accent text-accent-foreground hover:brightness-95' : variant === 'danger' ? 'bg-destructive text-destructive-foreground' : variant === 'outline' ? 'border border-border bg-card text-foreground hover:bg-muted' : 'text-muted-foreground hover:bg-muted hover:text-foreground'}`} data-testid={testId || `button-${type}`}>{children}</button>;
}
function Status({ children, tone = 'mint' }: { children: ReactNode; tone?: 'mint' | 'coral' | 'red' | 'slate' }) {
  return <span className={`inline-flex items-center rounded-full px-2 py-1 text-[11px] font-bold ${tone === 'mint' ? 'bg-secondary text-primary' : tone === 'coral' ? 'bg-accent/25 text-[hsl(13_65%_42%)]' : tone === 'red' ? 'bg-destructive/10 text-destructive' : 'bg-muted text-muted-foreground'}`}>{children}</span>;
}
function Skeleton({ className = '' }: { className?: string }) { return <div className={`animate-pulse rounded-lg bg-muted ${className}`} />; }
function Empty({ title, detail, action }: { title: string; detail?: string; action?: ReactNode }) { return <div className="grid min-h-48 place-items-center rounded-xl border border-dashed border-border bg-card p-8 text-center"><div><span className="mx-auto mb-3 grid size-10 place-items-center rounded-xl bg-secondary text-primary"><ClipboardList size={18} /></span><h3 className="font-bold">{title}</h3>{detail && <p className="mt-1 text-sm text-muted-foreground">{detail}</p>}{action && <div className="mt-4">{action}</div>}</div></div>; }

