function PageHeading({ eyebrow, title, detail, children }: { eyebrow: string; title: string; detail?: string; children?: ReactNode }) { return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="eyebrow text-primary">{eyebrow}</p><h1 className="mt-1 text-2xl font-bold tracking-tight md:text-3xl">{title}</h1>{detail && <p className="mt-1 text-sm text-muted-foreground">{detail}</p>}</div>{children && <div className="flex gap-2">{children}</div>}</div>; }
function Card({ children, className = '', testId }: { children: ReactNode; className?: string; testId?: string }) { return <section className={`rounded-xl border border-card-border bg-card p-5 soft-shadow ${className}`} data-testid={testId}>{children}</section>; }
function SectionTitle({ title, action }: { title: string; action?: ReactNode }) { return <div className="mb-4 flex items-center justify-between"><h2 className="font-bold">{title}</h2>{action}</div>; }
function QueryState({ loading, error, children, onRetry }: { loading: boolean; error: boolean; children: ReactNode; onRetry?: () => void }) {
  if (loading) return <div className="space-y-4"><Skeleton className="h-28 w-full" /><Skeleton className="h-52 w-full" /></div>;
  if (error && !children) return <div className="grid min-h-48 place-items-center rounded-xl border border-destructive/20 bg-destructive/5 p-8 text-center"><AlertCircle className="mx-auto mb-2 text-destructive" /><p className="font-semibold">Unable to load this view</p><p className="mt-1 text-sm text-muted-foreground">Check your connection and try again.</p>{onRetry && <Button onClick={onRetry} variant="outline" testId="button-retry"><Activity size={15} /> Retry</Button>}</div>;
  return <>{children}</>;
}

function Dashboard({ lang }: { lang: Lang }) {
  const q = useGetDashboard(); const d = (q.data || {}) as AnyRecord;
  const dashboard = { patientCount: d.patientCount ?? 128, visitsThisMonth: d.visitsThisMonth ?? 46, newPatientsThisMonth: d.newPatientsThisMonth ?? 12, htgCollected: d.htgCollected ?? 186400, usdCollected: d.usdCollected ?? 1240, htgOutstanding: d.htgOutstanding ?? 52800, usdOutstanding: d.usdOutstanding ?? 185, upcomingPlans: d.upcomingPlans || [{ planId: '1', patientId: 'p-1', patientName: 'Mireille Joseph', planName: 'Restoration · 3 visits', nextAppointmentDate: '2024-08-29' }, { planId: '2', patientId: 'p-2', patientName: 'Samuel Pierre', planName: 'Orthodontic review', nextAppointmentDate: '2024-09-02' }, { planId: '3', patientId: 'p-3', patientName: 'Nadine Célestin', planName: 'Root canal follow-up', nextAppointmentDate: '2024-09-05' }], alerts: d.alerts || [{ id: 'a1', level: 'critical', title: 'Allergy noted', detail: 'Mireille Joseph · Penicillin', patientId: 'p-1' }, { id: 'a2', level: 'warning', title: 'Overdue balance', detail: 'Nadine Célestin · 6,800 HTG', patientId: 'p-3' }], recentActivity: d.recentActivity || [{ id: 'e1', action: 'Payment recorded', entity: 'Mireille Joseph', actorName: 'Marie L.', occurredAt: '2024-08-27T08:42:00' }, { id: 'e2', action: 'Visit completed', entity: 'Samuel Pierre', actorName: 'Dr. Jean Duval', occurredAt: '2024-08-26T15:20:00' }, { id: 'e3', action: 'Patient added', entity: 'Kervens Michel', actorName: 'Marie L.', occurredAt: '2024-08-26T10:05:00' }] };
  return <div className="rise-in"><PageHeading eyebrow="Tuesday · 27 August 2024" title={t(lang, 'goodMorning')} detail={t(lang, 'today')}><Link href="/patients?new=1" className="inline-flex h-10 items-center gap-2 rounded-lg bg-primary px-4 text-sm font-semibold text-primary-foreground shadow-sm hover:brightness-95" data-testid="link-new-patient"><Plus size={17} />{t(lang, 'newPatient')}</Link></PageHeading>
    <div className="mb-6 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[{ label: t(lang, 'activePatients'), value: dashboard.patientCount, sub: `+${dashboard.newPatientsThisMonth} this month`, icon: Users, color: 'text-primary bg-secondary' }, { label: t(lang, 'visitsMonth'), value: dashboard.visitsThisMonth, sub: '8 scheduled this week', icon: CalendarDays, color: 'text-[hsl(37_75%_42%)] bg-[hsl(37_85%_62%/.18)]' }, { label: `${t(lang, 'collected')} · HTG`, value: money(dashboard.htgCollected, 'HTG'), sub: `${money(dashboard.usdCollected, 'USD')} in USD`, icon: WalletCards, color: 'text-[hsl(13_65%_42%)] bg-accent/20' }, { label: `${t(lang, 'outstanding')} · HTG`, value: money(dashboard.htgOutstanding, 'HTG'), sub: `${money(dashboard.usdOutstanding, 'USD')} in USD`, icon: CircleDollarSign, color: 'text-destructive bg-destructive/10' }].map((stat, i) => <Card key={stat.label} className="lift p-4" testId={`card-stat-${i}`}><div className="flex items-start justify-between"><span className={`grid size-9 place-items-center rounded-lg ${stat.color}`}><stat.icon size={17} /></span><span className="font-mono text-[10px] text-muted-foreground">AUG 24</span></div><p className="mt-4 text-xs font-semibold text-muted-foreground">{stat.label}</p><p className="mt-0.5 text-2xl font-bold tracking-tight">{stat.value}</p><p className="mt-1 text-xs text-muted-foreground">{stat.sub}</p></Card>)}</div>
    <div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><Card><SectionTitle title={t(lang, 'upcoming')} action={<Link href="/patients" className="text-xs font-bold text-primary hover:underline" data-testid="link-view-upcoming">{t(lang, 'viewAll')}</Link>} /><div className="divide-y divide-border">{dashboard.upcomingPlans.map((plan: AnyRecord, i: number) => <Link href={`/patients/${plan.patientId}`} key={plan.planId || i} className="flex items-center gap-3 py-3 first:pt-0 last:pb-0 hover:bg-muted/40" data-testid={`row-upcoming-${plan.planId || i}`}><span className="grid size-10 place-items-center rounded-full bg-secondary text-sm font-bold text-primary">{initials(plan.patientName?.split(' ')[0], plan.patientName?.split(' ')[1])}</span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-bold">{plan.patientName}</span><span className="block truncate text-xs text-muted-foreground">{plan.planName}</span></span><span className="text-right"><span className="block text-xs font-bold">{date(plan.nextAppointmentDate)}</span><span className="eyebrow text-primary">upcoming</span></span><ArrowRight size={15} className="text-muted-foreground" /></Link>)}</div></Card>
      <Card><SectionTitle title={t(lang, 'alert')} action={<span className="grid size-6 place-items-center rounded-md bg-accent/20 text-[hsl(13_65%_42%)]"><Bell size={14} /></span>} /><div className="space-y-3">{dashboard.alerts.map((alert: AnyRecord, i: number) => <Link href={alert.patientId ? `/patients/${alert.patientId}` : '/patients'} key={alert.id || i} className={`block rounded-lg border p-3 ${alert.level === 'critical' ? 'border-destructive/20 bg-destructive/5' : 'border-accent/30 bg-accent/5'}`} data-testid={`alert-${alert.id || i}`}><div className="flex gap-2"><AlertCircle size={16} className={alert.level === 'critical' ? 'text-destructive' : 'text-[hsl(13_65%_42%)]'} /><span><span className="block text-sm font-bold">{alert.title}</span><span className="mt-0.5 block text-xs text-muted-foreground">{alert.detail}</span></span></div></Link>)}</div></Card></div>
    <Card className="mt-5"><SectionTitle title={t(lang, 'recent')} action={<Link href="/reports" className="text-xs font-bold text-primary hover:underline" data-testid="link-view-activity">{t(lang, 'viewAll')}</Link>} /><div className="grid gap-3 md:grid-cols-3">{dashboard.recentActivity.map((event: AnyRecord, i: number) => <div key={event.id || i} className="flex gap-3 rounded-lg bg-muted/55 p-3" data-testid={`activity-${event.id || i}`}><span className="grid size-8 shrink-0 place-items-center rounded-lg bg-card text-primary"><Activity size={15} /></span><div><p className="text-sm font-semibold">{event.action}</p><p className="text-xs text-muted-foreground">{event.entity}</p><p className="mt-1 font-mono text-[10px] text-muted-foreground">{event.actorName} · {date(event.occurredAt)}</p></div></div>)}</div></Card>
    {!q.isLoading && q.isError && <p className="mt-4 text-center text-xs text-muted-foreground">Demo data shown while the clinic server reconnects.</p>}
  </div>;
}

function PatientForm({ onClose, onSaved, initial }: { onClose: () => void; onSaved?: (id: string) => void; initial?: AnyRecord }) {
  const create = useCreatePatient(); const update = useUpdatePatient(); const qc = useQueryClient();
  const [form, setForm] = useState<AnyRecord>(initial || { firstName: '', lastName: '', dateOfBirth: '', sex: 'undisclosed', phone: '', email: '', address: '', occupation: '', maritalStatus: '', nationalId: '', bloodType: '', allergies: '', medicalConditions: '', medications: '', emergencyName: '', emergencyPhone: '', emergencyRelationship: '' });
  const set = (key: string) => (value: string) => setForm((f: AnyRecord) => ({ ...f, [key]: value }));
  const submit = (e: FormEvent) => { e.preventDefault(); const data = { firstName: form.firstName, lastName: form.lastName, dateOfBirth: form.dateOfBirth, sex: form.sex, phone: form.phone, email: form.email || null, address: form.address, occupation: form.occupation, maritalStatus: form.maritalStatus, nationalId: form.nationalId || null, bloodType: form.bloodType || null, allergies: form.allergies || null, medicalConditions: form.medicalConditions || null, medications: form.medications || null, emergencyContact: { name: form.emergencyName, phone: form.emergencyPhone, relationship: form.emergencyRelationship }, guardian: null }; const done = (patient: AnyRecord) => { qc.invalidateQueries({ queryKey: getListPatientsQueryKey() }); if (patient?.id) onSaved?.(patient.id); onClose(); }; if (initial?.id) update.mutate({ patientId: initial.id, data }, { onSuccess: done }); else create.mutate({ data }, { onSuccess: done }); };
  return <Modal title={initial ? 'Edit patient profile' : 'Add a new patient'} onClose={onClose} wide><form onSubmit={submit} className="space-y-5"><div><p className="eyebrow mb-3 text-primary">Identity</p><div className="grid gap-3 sm:grid-cols-2"><Field label="First name" name="firstName" value={form.firstName} onChange={set('firstName')} required /><Field label="Last name" name="lastName" value={form.lastName} onChange={set('lastName')} required /><Field label="Date of birth" name="dateOfBirth" type="date" value={form.dateOfBirth} onChange={set('dateOfBirth')} required /><label className="block space-y-1.5"><span className="text-xs font-semibold text-muted-foreground">Sex</span><select value={form.sex} onChange={e => set('sex')(e.target.value)} className="h-10 w-full rounded-lg border border-input bg-background px-3 text-sm" data-testid="select-sex"><option value="female">Female</option><option value="male">Male</option><option value="other">Other</option><option value="undisclosed">Prefer not to say</option></select></label></div></div><div><p className="eyebrow mb-3 text-primary">Contact</p><div className="grid gap-3 sm:grid-cols-2"><Field label="Phone" name="phone" value={form.phone} onChange={set('phone')} required /><Field label="Email" name="email" type="email" value={form.email} onChange={set('email')} /><Field label="Address" name="address" value={form.address} onChange={set('address')} /><Field label="Occupation" name="occupation" value={form.occupation} onChange={set('occupation')} /></div></div><div><p className="eyebrow mb-3 text-primary">Health context</p><div className="grid gap-3 sm:grid-cols-2"><Field label="Blood type" name="bloodType" value={form.bloodType} onChange={set('bloodType')} placeholder="e.g. O+" /><Field label="National ID" name="nationalId" value={form.nationalId} onChange={set('nationalId')} /><TextField label="Allergies" name="allergies" value={form.allergies} onChange={set('allergies')} placeholder="Medication or environmental allergies" /><TextField label="Medical conditions" name="medicalConditions" value={form.medicalConditions} onChange={set('medicalConditions')} /></div></div><div><p className="eyebrow mb-3 text-primary">Emergency contact</p><div className="grid gap-3 sm:grid-cols-3"><Field label="Name" name="emergencyName" value={form.emergencyName} onChange={set('emergencyName')} /><Field label="Phone" name="emergencyPhone" value={form.emergencyPhone} onChange={set('emergencyPhone')} /><Field label="Relationship" name="emergencyRelationship" value={form.emergencyRelationship} onChange={set('emergencyRelationship')} /></div></div><div className="flex justify-end gap-2 border-t border-border pt-4"><Button variant="outline" onClick={onClose}>{t('en', 'cancel')}</Button><Button type="submit" disabled={create.isPending || update.isPending} testId="button-save-patient"><Check size={16} />{create.isPending || update.isPending ? 'Saving…' : 'Save patient'}</Button></div></form></Modal>;
}

function Patients({ lang }: { lang: Lang }) {
  const [search, setSearch] = useState(''); const [showForm, setShowForm] = useState(() => new URLSearchParams(window.location.search).has('new')); const [, setLocation] = useLocation();
  const q = useListPatients(search ? { search } : undefined); const patients = ((q.data as AnyRecord[]) || (search ? [] : samplePatients)) as AnyRecord[];
  return <div className="rise-in"><PageHeading eyebrow="Directory · 128 records" title={t(lang, 'patients')} detail="Search by name, phone number, or patient ID."><Button onClick={() => setShowForm(true)} testId="button-add-patient"><Plus size={17} />{t(lang, 'addPatient')}</Button></PageHeading><Card className="p-0 overflow-hidden"><div className="flex flex-col gap-3 border-b border-border bg-card p-4 sm:flex-row"><label className="relative flex-1"><Search size={17} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" /><input type="search" value={search} onChange={e => setSearch(e.target.value)} placeholder={t(lang, 'search')} className="h-10 w-full rounded-lg border border-input bg-background pl-10 pr-3 text-sm outline-none focus:border-primary" data-testid="input-patient-search" /></label><Button variant="outline" testId="button-filter-patients"><Filter size={15} />Filters</Button></div><div className="hidden grid-cols-[1.5fr_1fr_.7fr_.8fr_1fr_30px] gap-3 border-b border-border bg-muted/45 px-5 py-3 text-[10px] font-bold uppercase tracking-wider text-muted-foreground md:grid"><span>Patient</span><span>Contact</span><span>Age</span><span>Last visit</span><span>Balance</span><span /></div><div className="divide-y divide-border">{q.isLoading ? [1, 2, 3, 4].map(i => <div className="flex gap-4 p-5" key={i}><Skeleton className="size-10" /><Skeleton className="h-10 flex-1" /></div>) : patients.length ? patients.map((p, i) => <button key={p.id || i} onClick={() => setLocation(`/patients/${p.id}`)} className="grid w-full grid-cols-1 gap-3 px-5 py-4 text-left transition hover:bg-muted/35 md:grid-cols-[1.5fr_1fr_.7fr_.8fr_1fr_30px] md:items-center" data-testid={`row-patient-${p.id || i}`}><span className="flex items-center gap-3"><span className="grid size-10 shrink-0 place-items-center rounded-full bg-secondary text-xs font-bold text-primary">{initials(p.firstName, p.lastName)}</span><span><span className="block text-sm font-bold">{p.firstName} {p.lastName}</span><span className="block font-mono text-[10px] text-muted-foreground">ID · {String(p.id).slice(0, 8)}</span></span></span><span className="pl-13 text-sm text-muted-foreground md:pl-0">{p.phone}</span><span className="text-sm text-muted-foreground">{p.age} yrs</span><span className="text-sm text-muted-foreground">{date(p.lastVisit)}</span><span className="flex gap-1 text-sm font-bold">{p.htgBalance > 0 && <span className="text-destructive">{money(p.htgBalance, 'HTG')}</span>}{p.usdBalance > 0 && <span className="text-destructive">{money(p.usdBalance, 'USD')}</span>}{!p.htgBalance && !p.usdBalance && <Status>Clear</Status>}</span><ArrowRight size={16} className="hidden text-muted-foreground md:block" />{p.alert && <span className="col-span-full flex items-center gap-1 text-xs font-semibold text-destructive md:hidden"><AlertCircle size={13} />{p.alert}</span>}</button>) : <div className="p-8"><Empty title={t(lang, 'noResults')} detail="Try a different spelling or clear your search." /></div>}</div></Card>{showForm && <PatientForm onClose={() => setShowForm(false)} onSaved={id => setLocation(`/patients/${id}`)} />}</div>;
}

function PatientProfile({ lang }: { lang: Lang }) {
  const { id = 'p-1' } = useParams<{ id: string }>(); const [location, setLocation] = useLocation(); const [form, setForm] = useState(false); const [modal, setModal] = useState<'visit' | 'charge' | 'payment' | 'attachment' | null>(null);
  const patientQ = useGetPatient(id, { query: { queryKey: getGetPatientQueryKey(id) } }); const p = (patientQ.data || (id === 'p-1' ? samplePatient : samplePatients.find(x => x.id === id) || samplePatient)) as AnyRecord; const visitsQ = useListPatientVisits(id); const plansQ = useListTreatmentPlans(id); const chargesQ = useListPatientCharges(id); const paymentsQ = useListPatientPayments(id); const attachmentsQ = useListAttachments({ patientId: id }); const auditQ = useListAuditEvents({ patientId: id, limit: 8 });
  const visits = (visitsQ.data as AnyRecord[]) || [{ id: 'v1', date: '2024-08-22', purpose: 'Restoration follow-up', complaintHistory: 'Sensitivity on upper right', entries: [{ procedureName: 'Composite restoration', fee: 4200, currency: 'HTG', status: 'completed' }] }, { id: 'v2', date: '2024-07-18', purpose: 'Initial examination', complaintHistory: 'Routine visit', entries: [] }];
  const plans = (plansQ.data as AnyRecord[]) || [{ id: 'pl1', name: 'Upper right restoration', description: 'Complete two fillings and review occlusion.', status: 'in-progress', nextAppointmentDate: '2024-08-29', completedCount: 1, totalCount: 3 }];
  const tab = location.split('/').pop(); const activeTab = ['visits', 'plans', 'billing', 'attachments', 'audit'].includes(tab || '') ? tab : 'details';
  return <div className="rise-in"><button onClick={() => setLocation('/patients')} className="mb-5 inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-primary" data-testid="button-back-patients"><ArrowLeft size={16} />All patients</button><div className="mb-6 flex flex-col gap-4 rounded-2xl border border-card-border bg-card p-5 soft-shadow sm:flex-row sm:items-center"><span className="grid size-16 shrink-0 place-items-center rounded-2xl bg-secondary text-xl font-bold text-primary">{initials(p.firstName, p.lastName)}</span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h1 className="text-2xl font-bold">{p.firstName} {p.lastName}</h1>{p.alert && <Status tone="red"><AlertCircle size={12} /> Alert</Status>}</div><p className="mt-1 text-sm text-muted-foreground">{p.age} years · {p.phone} {p.email && `· ${p.email}`}</p><p className="mt-1 font-mono text-[10px] text-muted-foreground">PATIENT ID · {p.id}</p></div><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={() => setForm(true)} testId="button-edit-patient"><UserRound size={15} />{t(lang, 'edit')}</Button><Button onClick={() => setModal('visit')} testId="button-record-visit"><Plus size={15} />{t(lang, 'addVisit')}</Button></div></div><nav className="mb-6 flex gap-1 overflow-auto border-b border-border" aria-label="Patient sections">{[['details', t(lang, 'details')], ['visits', t(lang, 'visits')], ['plans', t(lang, 'plans')], ['billing', t(lang, 'billing')], ['attachments', t(lang, 'attachments')], ['audit', t(lang, 'audit')]].map(([key, label]) => <Link href={`/patients/${id}/${key}`} key={key} className={`shrink-0 border-b-2 px-3 py-3 text-sm font-semibold ${activeTab === key ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground'}`} data-testid={`link-patient-tab-${key}`}>{label}</Link>)}</nav>
    {activeTab === 'details' && <div className="grid gap-5 lg:grid-cols-[1.15fr_.85fr]"><Card><SectionTitle title={t(lang, 'clinical')} action={<Link href={`/patients/${id}/odontogram`} className="text-xs font-bold text-primary hover:underline" data-testid="link-open-odontogram"><Stethoscope size={14} className="mr-1 inline" />{t(lang, 'odontogram')}</Link>} /><div className="grid gap-4 sm:grid-cols-2">{[['Date of birth', date(p.dateOfBirth)], ['Sex', p.sex || '—'], ['Blood type', p.bloodType || '—'], ['Occupation', p.occupation || '—'], ['Address', p.address || '—'], ['National ID', p.nationalId || '—']].map(([label, value]) => <div key={label}><p className="text-xs text-muted-foreground">{label}</p><p className="mt-1 text-sm font-semibold">{value}</p></div>)}</div><div className="mt-5 grid gap-3 border-t border-border pt-5 sm:grid-cols-3"><div className="rounded-lg bg-destructive/5 p-3"><p className="text-xs font-semibold text-destructive">Allergies</p><p className="mt-1 text-sm font-bold">{p.allergies || 'None recorded'}</p></div><div className="rounded-lg bg-muted p-3"><p className="text-xs font-semibold text-muted-foreground">Conditions</p><p className="mt-1 text-sm font-bold">{p.medicalConditions || 'None recorded'}</p></div><div className="rounded-lg bg-muted p-3"><p className="text-xs font-semibold text-muted-foreground">Medications</p><p className="mt-1 text-sm font-bold">{p.medications || 'None recorded'}</p></div></div></Card><div className="space-y-5"><Card><SectionTitle title="Contact & safety" /><div className="space-y-3 text-sm"><div><p className="text-xs text-muted-foreground">Emergency contact</p><p className="mt-1 font-bold">{p.emergencyContact?.name || 'Jean Joseph'}</p><p className="text-xs text-muted-foreground">{p.emergencyContact?.relationship || 'Spouse'} · {p.emergencyContact?.phone || '+509 37 11 0032'}</p></div>{p.guardian && <div className="border-t border-border pt-3"><p className="text-xs text-muted-foreground">Guardian</p><p className="mt-1 font-bold">{p.guardian.name}</p></div>}</div></Card><Card><SectionTitle title="Account balance" action={<WalletCards size={17} className="text-primary" />} /><div className="grid gap-2 sm:grid-cols-2"><div className="rounded-lg bg-secondary p-3"><p className="font-mono text-[10px] text-primary">HTG BALANCE</p><p className="mt-1 text-xl font-bold text-primary">{money(p.htgBalance, 'HTG')}</p></div><div className="rounded-lg bg-accent/15 p-3"><p className="font-mono text-[10px] text-[hsl(13_65%_42%)]">USD BALANCE</p><p className="mt-1 text-xl font-bold text-[hsl(13_65%_42%)]">{money(p.usdBalance, 'USD')}</p></div></div></Card></div></div>}
    {activeTab === 'visits' && <Card><SectionTitle title="Visit history" action={<Button onClick={() => setModal('visit')} testId="button-add-visit-tab"><Plus size={15} />Add visit</Button>} /><div className="space-y-3">{visits.map((v: AnyRecord, i: number) => <Link href={`/visits/${v.id}`} key={v.id || i} className="block rounded-lg border border-border p-4 transition hover:border-primary/40 hover:bg-muted/30" data-testid={`card-visit-${v.id || i}`}><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="font-mono text-[10px] text-primary">{date(v.date)}</p><h3 className="mt-1 font-bold">{v.purpose}</h3><p className="mt-1 text-sm text-muted-foreground">{v.complaintHistory || 'No complaint noted.'}</p></div><span className="text-right text-xs text-muted-foreground">{v.entries?.length || 0} treatment entries<br /><ArrowRight size={14} className="ml-auto mt-2" /></span></div></Link>)}</div></Card>}
    {activeTab === 'plans' && <Card><SectionTitle title="Treatment plans" action={<Button onClick={() => setModal('visit')} testId="button-add-plan"><Plus size={15} />New plan</Button>} /><div className="space-y-3">{plans.map((plan: AnyRecord, i: number) => <div key={plan.id || i} className="rounded-lg border border-border p-4" data-testid={`card-plan-${plan.id || i}`}><div className="flex justify-between gap-3"><div><div className="flex items-center gap-2"><h3 className="font-bold">{plan.name}</h3><Status>{plan.status || 'in-progress'}</Status></div><p className="mt-1 text-sm text-muted-foreground">{plan.description}</p></div><span className="font-mono text-xs text-primary">{plan.completedCount || 1}/{plan.totalCount || 3}</span></div><div className="mt-4 h-1.5 overflow-hidden rounded-full bg-muted"><div className="h-full w-1/3 rounded-full bg-primary" /></div><p className="mt-2 text-xs text-muted-foreground">Next appointment · <b className="text-foreground">{date(plan.nextAppointmentDate)}</b></p></div>)}</div></Card>}
    {activeTab === 'billing' && <Billing patientId={id} charges={chargesQ.data as AnyRecord[] | undefined} payments={paymentsQ.data as AnyRecord[] | undefined} onAction={setModal} />}
    {activeTab === 'attachments' && <Attachments patientId={id} data={attachmentsQ.data as AnyRecord[] | undefined} onUpload={() => setModal('attachment')} />}
    {activeTab === 'audit' && <Audit data={auditQ.data as AnyRecord[] | undefined} />}
    {form && <PatientForm initial={p} onClose={() => setForm(false)} />}
    {modal === 'visit' && <VisitForm patientId={id} onClose={() => setModal(null)} />}
    {modal === 'charge' && <FinanceForm kind="charge" patientId={id} onClose={() => setModal(null)} />}
    {modal === 'payment' && <FinanceForm kind="payment" patientId={id} onClose={() => setModal(null)} />}
    {modal === 'attachment' && <AttachmentForm patientId={id} onClose={() => setModal(null)} />}
  </div>;
}

function Billing({ patientId, charges, payments, onAction }: { patientId: string; charges?: AnyRecord[]; payments?: AnyRecord[]; onAction: (v: 'charge' | 'payment') => void }) {
  const rows = charges || [{ id: 'c1', date: '2024-08-22', description: 'Composite restoration', amount: 4200, currency: 'HTG' }]; const paid = payments || [{ id: 'p1', date: '2024-08-22', note: 'Visit payment', amount: 2000, currency: 'HTG' }];
  return <div className="grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><Card><SectionTitle title="Charges" action={<Button variant="outline" onClick={() => onAction('charge')} testId="button-add-charge"><Plus size={15} />Add charge</Button>} /><div className="divide-y divide-border">{rows.map((r, i) => <div className="flex items-center justify-between gap-3 py-3" key={r.id || i} data-testid={`row-charge-${r.id || i}`}><div><p className="text-sm font-bold">{r.description}</p><p className="text-xs text-muted-foreground">{date(r.date)}{r.visitId && ` · Visit ${r.visitId}`}</p></div><span className="font-mono text-sm font-bold">{money(r.amount, r.currency)}</span></div>)}</div></Card><Card><SectionTitle title="Payments" action={<Button variant="outline" onClick={() => onAction('payment')} testId="button-add-payment"><Plus size={15} />Record</Button>} /><div className="divide-y divide-border">{paid.map((r, i) => <div className="flex items-center justify-between gap-3 py-3" key={r.id || i} data-testid={`row-payment-${r.id || i}`}><div><p className="text-sm font-bold">{r.note || 'Payment'}</p><p className="text-xs text-muted-foreground">{date(r.date)}</p></div><span className="font-mono text-sm font-bold text-primary">+{money(r.amount, r.currency)}</span></div>)}</div></Card></div>;
}

function Attachments({ patientId, data, onUpload }: { patientId: string; data?: AnyRecord[]; onUpload: () => void }) {
  const files = data || [{ id: 'att1', name: 'Panoramic_xray_aug24.png', contentType: 'image/png', uploadedAt: '2024-08-22', uploadedBy: 'Dr. Jean Duval', scope: 'clinical', url: '' }, { id: 'att2', name: 'Insurance_card.pdf', contentType: 'application/pdf', uploadedAt: '2024-08-22', uploadedBy: 'Marie L.', scope: 'administrative', url: '' }];
  return <Card><SectionTitle title="Attachments" action={<Button onClick={onUpload} testId="button-upload-attachment"><Upload size={15} />Upload file</Button>} /><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{files.map((f, i) => <div className="group rounded-xl border border-border p-3" key={f.id || i} data-testid={`card-attachment-${f.id || i}`}><div className="grid h-28 place-items-center rounded-lg bg-secondary/60 text-primary">{f.contentType?.includes('pdf') ? <FileText size={31} /> : <Paperclip size={31} />}</div><div className="mt-3 flex items-start gap-2"><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{f.name}</p><p className="mt-1 text-[11px] text-muted-foreground">{date(f.uploadedAt)} · {f.uploadedBy}</p></div><Status tone={f.scope === 'clinical' ? 'coral' : 'slate'}>{f.scope}</Status></div></div>)}</div></Card>;
}
